assets/home-focus.css.after:
body[data-page="home"] .home-work-card-copy>a{min-height:44px;display:inline-flex;align-items:center}

/* Keep the existing demo card and attach the regional links as its footer. */
.home-crm-panel {
  min-width: 0;
  width: 100%;
  justify-self: center;
}
.home-crm-panel #intl-crm-preview {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}
.home-crm-markets {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0 12px;
  padding: 4px 10px;
  border: 1px solid #60748a;
  border-top: 0;
  border-radius: 0 0 12px 12px;
  background: #1b2a3d;
  color: #f6f4ee;
  font-size: .875rem;
  line-height: 1.4;
}
.home-crm-market-options {
  display: flex;
  gap: 4px;
}
.home-crm-markets a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  color: var(--brand-champagne);
  text-decoration: underline;
  text-underline-offset: 3px;
}
.home-crm-markets a:focus-visible {
  outline: 2px solid var(--brand-champagne);
  outline-offset: 1px;
}
@media (max-width: 1100px) {
  .home-crm-panel { max-width: 680px; }
}
